/// Returns the top N most common (well-known) ports for quick scanning.
pub fn top_ports(n: u16) -> Vec<u16> {
    let top = vec![
        21, 22, 23, 25, 53, 80, 110, 111, 123, 135, 139, 143, 161, 162, 179,
        389, 443, 445, 465, 500, 502, 512, 513, 514, 515, 520, 523, 540, 554,
        587, 623, 626, 631, 636, 646, 666, 691, 749, 873, 902, 989, 990, 992,
        993, 995, 1080, 1099, 1194, 1214, 1220, 1234, 1241, 1311, 1337, 1352,
        1381, 1394, 1414, 1433, 1434, 1484, 1494, 1521, 1524, 1527, 1540, 1583,
        1701, 1720, 1723, 1741, 1755, 1761, 1801, 1812, 1813, 1863, 1880, 1883,
        1900, 1935, 1960, 1961, 1972, 1984, 1991, 1998, 2000, 2001, 2002, 2003,
        2005, 2010, 2022, 2049, 2082, 2083, 2086, 2087, 2095, 2096, 2100, 2181,
        2200, 2222, 2302, 2368, 2375, 2376, 2424, 2443, 2447, 2480, 2483, 2484,
    ];
    top.into_iter().take(n as usize).collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_known_service() {
        assert_eq!(get_service_name(22), "SSH");
        assert_eq!(get_service_name(80), "HTTP");
        assert_eq!(get_service_name(443), "HTTPS");
        assert_eq!(get_service_name(3306), "MySQL");
    }

    #[test]
    fn test_unknown_port() {
        assert_eq!(get_service_name(1), "");
    }

    #[test]
    fn test_top_ports_count() {
        assert_eq!(top_ports(10).len(), 10);
        assert_eq!(top_ports(50).len(), 50);
        assert!(top_ports(5).contains(&22));
    }
}
